    30  IPv4OptionBuilder::IPv4OptionBuilder(IPv4OptionTypes optionType, const std::vector<IPv4Address>& ipList)
    31  {
    32          m_RecType = (uint8_t)optionType;
    33          m_RecValueLen = ipList.size() * sizeof(uint32_t) + sizeof(uint8_t);
    34          m_RecValue = new uint8_t[m_RecValueLen];
    35
    36          size_t curOffset = 0;
    37          m_RecValue[curOffset++] = 0; // init pointer value
    38
    39          bool firstZero = false;
    40          for (std::vector<IPv4Address>::const_iterator iter = ipList.begin(); iter != ipList.end(); iter++)
    41          {
    42                  uint32_t ipAddrAsInt = iter->toInt();
    43
    44                  if (!firstZero)
    45                          m_RecValue[0] += (uint8_t)4;
    46
    47                  if (!firstZero && ipAddrAsInt == 0)
    48                          firstZero = true;
    49
    50                  memcpy(m_RecValue + curOffset, &ipAddrAsInt, sizeof(uint32_t));
    51                  curOffset += sizeof(uint32_t);
    52          }
    53
    54          m_BuilderParamsValid = true;
    55  }
