    57  IPv4OptionBuilder::IPv4OptionBuilder(const IPv4TimestampOptionValue& timestampValue)
    58  {
    59          m_RecType = (uint8_t)IPV4OPT_Timestamp;
    60          m_RecValueLen = 0;
    61          m_RecValue = nullptr;
    62
    63          if (timestampValue.type == IPv4TimestampOptionValue::Unknown)
    64          {
    65                  PCPP_LOG_ERROR("Cannot build timestamp option of type IPv4TimestampOptionValue::Unknown");
    66                  m_BuilderParamsValid = false;
    67                  return;
    68          }
