    70          if (timestampValue.type == IPv4TimestampOptionValue::TimestampsForPrespecifiedIPs)
    71          {
    72                  PCPP_LOG_ERROR("Cannot build timestamp option of type IPv4TimestampOptionValue::TimestampsForPrespecifiedIPs - this type is not supported");
    73                  m_BuilderParamsValid = false;
    74                  return;
    75          }
    76
    77          if (timestampValue.type == IPv4TimestampOptionValue::TimestampAndIP && timestampValue.timestamps.size() != timestampValue.ipAddresses.size())
    78          {
    79                  PCPP_LOG_ERROR("Cannot build timestamp option of type IPv4TimestampOptionValue::TimestampAndIP because number of timestamps and IP addresses is not equal");
    80                  m_BuilderParamsValid = false;
    81                  return;
    82          }
